  'Tympanites' => 'Abdominal distension caused by excessive gas in the stomach or intestines, producing a drum-like sound on percussion and sometimes pain, belching, or altered bowel movements.'
}.freeze

text = File.read(FILE)
changed = 0
text = text.gsub(/^\\medterm\{([^}]*)\} ([^\n]*)/) do |line|
  term = Regexp.last_match(1)
  old = Regexp.last_match(2)
  next line unless old.match?(/is a medical term used to describe|is a disease, symptom, syndrome|is an anatomical or histologic|is a biological, genetic|is a healthcare or clinical-care|is a diagnostic or laboratory/i)
  replacement = SPECIAL[term]
  next line unless replacement
  changed += 1
  "\\medterm{#{term}} #{replacement}"
end
File.write(FILE, text)
puts "updated=#{changed}"
